import{_t as e,it as t,n,rt as r}from"./chunks/framework.CfRzmOnu.js";var i=JSON.parse(`{"title":"打印模板","description":"","frontmatter":{},"headers":[],"relativePath":"backend/printing.md","filePath":"backend/printing.md","lastUpdated":1792672955000}`),a={name:`backend/printing.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="打印模板" tabindex="-1">打印模板 <a class="header-anchor" href="#打印模板" aria-label="Permalink to “打印模板”">​</a></h1><p>打印能力由独立模块 <code>modules/XiHan.BasicApp.Printing</code> 承载（后端）与 <code>frontend/src/modules/printing</code> + <code>@xihan/printing</code> 功能包承载（前端）：可视化设计打印模板、按编码解析、浏览器预览打印与本机静默直打。不需要此能力的部署可整体卸载模块（见仓库 README「卸载可选模块」）。</p><h2 id="能力与边界" tabindex="-1">能力与边界 <a class="header-anchor" href="#能力与边界" aria-label="Permalink to “能力与边界”">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>依赖</th><th>说明</th></tr></thead><tbody><tr><td>模板设计器</td><td>仅浏览器</td><td><a href="https://print.docs.xihanfun.com" target="_blank" rel="noreferrer">XiHan 打印设计器</a> 可视化设计，模板 JSON（<code>schemaVersion</code> 为 1 的打印模板）存 <code>Sys_Print_Template</code></td></tr><tr><td>浏览器打印</td><td>仅浏览器</td><td><code>previewPrintByCode</code> 在看不见的 iframe 里排好输出页再调起浏览器打印对话框，任何部署形态可用；传对象数组时各自分页后一次打印</td></tr><tr><td>打印机列表 / 静默直打</td><td><strong>XiHan 打印客户端</strong></td><td><code>listPrinters</code> / <code>refreshPrinters</code> / <code>directPrintByCode</code> 要求每台操作机安装并运行 <a href="https://print.docs.xihanfun.com/guide/client" target="_blank" rel="noreferrer">打印客户端</a>，前端经本机 WebSocket 连接；连不上、未授权或打印机出错时这三条路径按错误码明确报错，不退回浏览器打印</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">部署前提</p><p>静默直打是<strong>企业内网桌面场景</strong>的能力：纯 Web 部署（用户不装桌面客户端）只有设计器与浏览器打印可用。网站第一次连接时，客户端在桌面上弹出授权窗口，允许后才能打印。生产站点要用 HTTPS；Chrome / Edge 访问本机应用要先过浏览器的本机网络访问授权，嵌在 iframe 里时每层都要允许 <code>loopback-network</code>。</p></div><h2 id="作用域模型" tabindex="-1">作用域模型 <a class="header-anchor" href="#作用域模型" aria-label="Permalink to “作用域模型”">​</a></h2><p>模板分两种作用域，解析顺序由 <code>PrintTemplateScope</code> 控制（<code>Application/Services/PrintTemplateResolver.cs</code>）：</p><ul><li><strong>Tenant</strong>：租户私有模板，<code>TenantId</code> = 当前租户；</li><li><strong>Global</strong>：平台全局模板（<code>TenantId = 0</code>），<code>AllowTenantUse = true</code> 时对业务租户开放解析；</li><li><strong>Auto</strong>（默认）：先找租户私有，未命中回退开放的全局模板。</li></ul><p>同租户内启用模板的 <code>TemplateCode</code> 唯一；解析结果带分布式缓存（30 分钟，写路径经事务感知失效器整体清除）。</p><h2 id="权限码" tabindex="-1">权限码 <a class="header-anchor" href="#权限码" aria-label="Permalink to “权限码”">​</a></h2><p>前缀 <code>print-template:</code>（<code>Domain/Permissions/PrintingPermissionCodes.cs</code>）：<code>read</code> / <code>create</code> / <code>update</code> / <code>status</code> / <code>delete</code> / <code>use</code> 两侧生效、可授予租户（租户角色与套餐白名单由运营授予；演示数据里的租户管理员角色取租户能生效的全部权限）；<code>global-manage</code> 作用侧为平台（管理全局模板与租户开放状态；由权限种子声明，只在平台生效、进不了套餐白名单）。</p><h2 id="数据源目录" tabindex="-1">数据源目录 <a class="header-anchor" href="#数据源目录" aria-label="Permalink to “数据源目录”">​</a></h2><p>模板可绑定「代码注册数据源」获得字段素材与样例数据：字段列在设计器物料面板的「字段」一组，拖上画布就是绑好的元素（图片、条码、二维码字段生成对应元素，明细表生成表格）。目录以<strong>后端注册表为单一事实源</strong>（<code>Domain/DataSources/IPrintDataSourceRegistry</code>）：</p><ul><li><strong>注册</strong>：业务模块在自己的 <code>ConfigureServices</code> 中调 <code>services.RegisterPrintDataSource(definition)</code> 登记定义（字段契约 + 静态样例 JSON）；打印模块内置示例数据源 <code>system.print-demo</code> 随模块自注册。</li><li><strong>启动期校验</strong>：应用启动即收纳全部登记项，重复编码、非法字段契约（未知类型/重复字段/空列明细/非法控件类型）、坏样例 JSON（不可解析或根节点不是对象/数组）都会让启动直接失败。</li><li><strong>查询</strong>：<code>GET /PrintDataSourceQuery/List</code> 输出目录，持 <code>print-template:read</code> 或 <code>print-template:use</code> 任一权限即可访问（分别服务模板管理与业务打印两条路径）。</li><li><strong>写路径 fail-closed</strong>：创建/更新模板时绑定未注册的 <code>DataSourceCode</code> 直接被拒；解析读路径不校验（既有模板宽限，前端打印使用点仍会按未注册报错）。</li><li><strong>前端惰性拉取</strong>：设计器与打印路径首次用到目录时经上面的查询端点拉取并并入本地注册表（自由模板打印不依赖目录）；<code>registerPrintDataSource</code> 仍可用于纯前端数据源；单个坏目录项只跳过自身、不影响其余数据源。</li></ul><p>由此推出的两条约束：</p><ul><li>数据源随后端代码发版，删除/改名会使既有模板的绑定失效（打印时报「数据源未注册」）；</li><li>不绑数据源的「自由模板」不受上述影响：直打按空记录打印，样例预览的表单按模板引用的字段生成。</li></ul><p>绑定了数据源时，模板引用了、数据源却没登记的字段在模板设置里提示数量（不阻断保存与打印，调用方要传这些字段），样例预览的表单也为它们单独列出输入项。</p><p>模板 JSON 的服务端校验只做最小结构检查（JSON 对象、<code>schemaVersion</code> 为 1、<code>pages</code> 是非空的对象数组），完整校验在前端保存前由设计器做。库里存着旧格式内容的模板，打印时明确报格式错误；在打印模板页打开时换成空白模板并提示，重新设计保存后覆盖。</p><h2 id="演示模板" tabindex="-1">演示模板 <a class="header-anchor" href="#演示模板" aria-label="Permalink to “演示模板”">​</a></h2><p>配置 <code>Saas:Seed:EnableDemoData</code> 为 <code>true</code> 时，打印模块多注册五个演示数据源，并写入六张平台全局模板（<code>TenantId = 0</code>、对租户开放、启用）；开关关着时数据源目录里没有它们，库里也不写这些模板。种子按模板编码先查后写，重复启动不重复插入，已有的模板不改、删掉的不补回。</p><table tabindex="0"><thead><tr><th>模板编码</th><th>名称</th><th>所绑数据源</th><th>演示什么</th></tr></thead><tbody><tr><td><code>demo.pickup-receipt</code></td><td>取件凭条</td><td><code>demo.pickup-receipt</code></td><td>最小模板：模板文字、放不下时缩小字号</td></tr><tr><td><code>demo.delivery-note</code></td><td>送货单</td><td><code>demo.delivery-note</code></td><td>页眉标题、页码、日期格式、明细表跨页、序号列与合计行</td></tr><tr><td><code>demo.formats</code></td><td>格式示例</td><td><code>demo.formats</code></td><td>数字、百分比、日期、人民币大写、中文数字、值映射、表达式、空值与占位模板</td></tr><tr><td><code>demo.inspection</code></td><td>设备巡检记录</td><td><code>demo.inspection</code></td><td>首页页眉、长文本、表头每页重复、本页计数、带数据占位的水印</td></tr><tr><td><code>demo.outage-notice</code></td><td>停电检修通知</td><td><code>demo.outage-notice</code></td><td>静态富文本与行内字段，数据里的 HTML 排成富文本（样例故意带的脚本被丢弃）</td></tr><tr><td><code>demo.element-overview</code></td><td>打印元素总览</td><td><code>system.print-demo</code></td><td>全部元素种类；七种条码与四种二维码；直线、矩形、椭圆；表格里的条码列与补空行；首页、奇偶、末页的页眉页脚；两个页面模板接续页码；水印与只在预览中显示的元素</td></tr></tbody></table><p>前五张对应<a href="https://print.docs.xihanfun.com" target="_blank" rel="noreferrer">打印设计器文档站</a>的模板示例，数据源的样例数据就是示例里的数据。模板与数据源放在 <code>Infrastructure/Seeders/Demo/</code> 下随程序集发布；前端 <code>packages/printing/demo-templates.test.ts</code> 读同一批文件，核对每张模板通过设计器的完整校验、按样例数据排版不出错误级诊断（条码与二维码取值不合法、图片地址不安全、表达式出错，在预览里都是报错占位）、引用的字段都在所绑数据源里登记。</p><h2 id="已知限制" tabindex="-1">已知限制 <a class="header-anchor" href="#已知限制" aria-label="Permalink to “已知限制”">​</a></h2><ul><li><code>previewPrintByCode</code> 的完成信号仅表示打印对话框已调起，无法得知用户在系统对话框中点了打印还是取消；</li><li>直打依赖的打印机名单来自客户端所在机器，跨机器无共享；打印机偏好存浏览器 <code>localStorage</code>（按 用户×租户×模板 隔离，不上传服务端）。</li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};